// =============================================================
// components/ServiceCard/ServiceCard.jsx
// Clickable card showing a single service summary.
// Props: service (object from config), active, onClick
// =============================================================

import styles from './ServiceCard.module.css';

export default function ServiceCard({ service, active = false, onClick }) {
  return (
    <article
      className={[styles.card, active ? styles.active : ''].join(' ')}
      onClick={onClick}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => e.key === 'Enter' && onClick?.()}
      aria-pressed={active}
    >
      <div className={styles.icon}>{service.icon}</div>
      <h3 className={styles.title}>{service.title}</h3>
      <p className={styles.desc}>{service.shortDesc}</p>
      <span className={styles.delay}>⏱ {service.delay}</span>
      <span className={styles.cta}>Voir la procédure →</span>
    </article>
  );
}
