// pages/Services/Services.jsx
// Full services listing with expandable detail panels.
// =============================================================

import { useState } from 'react';
import { useParams } from 'react-router-dom';
import Section     from '../../components/Section/Section';
import ServiceCard from '../../components/ServiceCard/ServiceCard';
import Button      from '../../components/Button/Button';
import { SITE_CONFIG, getWhatsAppUrl } from '../../config/site';
import styles from './Services.module.css';

export default function Services() {
  const [activeService, setActiveService] = useState(null);

  return (
    <>
      {/* Page header */}
      <div className={styles.pageHeader}>
        <div className="container">
          <h1 className={styles.pageTitle}>Nos services</h1>
          <p className={styles.pageSub}>
            Sélectionnez un service pour voir la procédure complète et nous contacter directement.
          </p>
        </div>
      </div>

      {/* Services grid */}
      <Section variant="light">
        <div className={styles.grid}>
          {SITE_CONFIG.services.map((service, i) => (
            <div key={service.id} id={service.id}>
              <ServiceCard
                service={service}
                active={activeService === i}
                onClick={() => setActiveService((p) => (p === i ? null : i))}
              />
            </div>
          ))}
        </div>

        {/* Expanded service detail */}
        {activeService !== null && (
          <div className={styles.detail}>
            {(() => {
              const s = SITE_CONFIG.services[activeService];
              return (
                <>
                  <div className={styles.detailHeader}>
                    <div>
                      <h2 className={styles.detailTitle}>
                        {s.icon} {s.title}
                      </h2>
                      <span className={styles.detailBadge}>⏱ {s.delay}</span>
                    </div>
                    <button
                      className={styles.closeBtn}
                      onClick={() => setActiveService(null)}
                    >
                      ✕ Fermer
                    </button>
                  </div>

                  <p className={styles.detailDesc}>{s.fullDesc}</p>

                  <h3 className={styles.stepsLabel}>Étapes de la procédure</h3>
                  <div className={styles.steps}>
                    {s.steps.map((step, i) => (
                      <div key={i} className={styles.stepItem}>
                        <div className={styles.stepBullet}>{i + 1}</div>
                        <p className={styles.stepText}>{step}</p>
                      </div>
                    ))}
                  </div>

                  <div className={styles.detailActions}>
                    <Button
                      variant="whatsapp"
                      href={getWhatsAppUrl(
                        `Bonjour, je souhaite obtenir des informations sur : ${s.title}. Pouvez-vous me guider ?`
                      )}
                    >
                      💬 Contacter via WhatsApp
                    </Button>
                    <Button variant="navy" href={`tel:${SITE_CONFIG.phone}`}>
                      📞 Appeler directement
                    </Button>
                  </div>
                </>
              );
            })()}
          </div>
        )}
      </Section>

      {/* Info band */}
      <Section variant="navy" title="Besoin d'aide pour choisir ?" subtitle="Notre facilitateur évalue gratuitement votre situation">
        <div style={{ textAlign: 'center' }}>
          <Button variant="primary" size="lg" href={getWhatsAppUrl(
            'Bonjour, je ne sais pas encore quel service correspond à ma situation. Pouvez-vous m\'aider à identifier mes besoins ?'
          )}>
            💬 Obtenir un conseil gratuit
          </Button>
        </div>
      </Section>
    </>
  );
}
